/** Output đã lưu kèm lệnh; dòng "exit=N" cuối thành "$ echo $?" + N như terminal thật. */
const RUN = (key, cmd, nhan) => mau(`$ ${cmd}\n` + OUT[key].replace(/exit=(\d+)\n?$/, '$ echo $?\n$1'), nhan);
