const CAU_PV = (en) => [
  ['1', 'What are the four principles of object-oriented programming?', 'tra-loi-1.txt', null, en ? 'Name all four in the first sentence (that is the "define" part), then spend the time on ONE example from your code. Nobody wants four textbook definitions.' : 'Nêu đủ bốn tên ngay câu đầu (đó là phần "định nghĩa"), rồi dành thời gian cho MỘT ví dụ từ mã của bạn. Không ai muốn nghe bốn định nghĩa sách giáo khoa.'],
  ['2', 'How does a HashMap work? What happens if a key class does not override equals and hashCode?', 'tra-loi-2.txt', 'hashmap', en ? 'The follow-up is almost always about equals/hashCode or about changing a key. Having run it once lets you say "I tested it", which is worth more than any definition.' : 'Câu hỏi nối tiếp gần như luôn là equals/hashCode hoặc đổi khoá. Đã từng chạy thử cho phép bạn nói "I tested it", đáng giá hơn mọi định nghĩa.'],
  ['3', 'What is a database index, and when does it not help?', 'tra-loi-3.txt', 'index', en ? '"When does it not help" is the trade-off part: functions on the column, low selectivity, slower writes.' : '"Khi nào không giúp" chính là phần đánh đổi: hàm bọc cột, độ chọn lọc thấp, ghi chậm hơn.'],
  ['4', 'What is a deadlock? How do you avoid it?', 'tra-loi-4.txt', 'deadlock', en ? 'Describe it with two concrete sessions, not with abstract "resources". Three ways to avoid it are enough.' : 'Tả bằng hai phiên cụ thể, đừng nói "tài nguyên" chung chung. Ba cách phòng là đủ.'],
  ['5', 'What is the difference between 401 and 403?', 'tra-loi-5b.txt', null, en ? 'Say the numbers as "four oh one" — and see below why "the approve endpoint" was rewritten.' : 'Đọc số là "four oh one" — và xem bên dưới vì sao cụm "the approve endpoint" phải viết lại.'],
  ['6', 'What is the N+1 problem in JPA?', 'tra-loi-6.txt', null, en ? 'Connect it to something you did. The capstone of lesson 8.2 had exactly this review comment.' : 'Nối với việc bạn đã làm. Capstone bài 8.2 có đúng góp ý review này.'],
  ['7', 'Why do you want to join FPT Software?', 'tra-loi-7.txt', null, en ? 'Talk about the kind of work (foreign clients, a large team, delivery), and give evidence that you already practise it. Do not recite facts about the company that you cannot check.' : 'Nói về kiểu công việc (khách nước ngoài, đội lớn, bàn giao sản phẩm), và đưa bằng chứng bạn đã luyện kiểu làm việc đó. Đừng đọc thuộc các con số về công ty mà bạn không kiểm được.'],
  ['8', 'Do you have any questions for us?', 'tra-loi-8.txt', null, en ? '"No" ends the interview badly. Two questions about the work and about feedback show you plan to learn there.' : 'Trả lời "No" kết thúc buổi phỏng vấn không đẹp. Hai câu hỏi về công việc và về phản hồi cho thấy bạn định học ở đó.'],
];

